mapper.select:
SELECT q.*, 
       CONVERT(COALESCE(c.display_name, q.category) USING utf8mb4) as categoryDisplayName,
       (SELECT COUNT(*) FROM moondap.balance_comments c WHERE c.question_id = q.id) AS comment_cnt
FROM moondap.balance_questions q
LEFT JOIN moondap.md_test_category c ON q.category = c.category_name


        AND q.status = #{status}


        AND q.is_spicy = 0


        AND q.category = #{category}


        AND q.user_id = #{userId}


ORDER BY q.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT q.*, CONVERT(COALESCE(c.display_name, q.category) USING utf8mb4) as categoryDisplayName FROM moondap.balance_questions q LEFT JOIN moondap.md_test_category c ON q.category = c.category_name
AND q.id = #{id}
AND q.is_spicy = 0
AND q.category = #{category}

choose.when:
SELECT COALESCE( (SELECT id FROM moondap.balance_questions WHERE id > #{id}
ORDER BY id ASC LIMIT 1), (SELECT id FROM moondap.balance_questions
ORDER BY id ASC LIMIT 1) )

choose.otherwise:
SELECT COALESCE( (SELECT id FROM moondap.balance_questions WHERE id < #{id}
ORDER BY id DESC LIMIT 1), (SELECT id FROM moondap.balance_questions
ORDER BY id DESC LIMIT 1) )

